import struct, sys
T_STOP=0; T_TRUE=1; T_FALSE=2; T_BYTE=3; T_I16=4; T_I32=5; T_I64=6; T_DOUBLE=7; T_BINARY=8; T_LIST=9; T_SET=10; T_MAP=11; T_STRUCT=12
class R:
    def __init__(self,b,idx=0): self.b=b; self.i=idx
    def read(self,n): x=self.b[self.i:self.i+n]; self.i+=n; return x
    def byte(self): x=self.b[self.i]; self.i+=1; return x
    def varint(self):
        shift=0; res=0
        while True:
            c=self.byte(); res|=(c&0x7f)<<shift
            if not c&0x80: break
            shift+=7
        return res
    def zig(self):
        n=self.varint(); return (n>>1)^-(n&1)

def read_val(r,t):
    if t==T_TRUE: return True
    if t==T_FALSE: return False
    if t==T_BYTE: return struct.unpack('b',r.read(1))[0]
    if t in (T_I16,T_I32,T_I64): return r.zig()
    if t==T_DOUBLE: return struct.unpack('<d',r.read(8))[0]
    if t==T_BINARY:
        l=r.varint(); return r.read(l)
    if t==T_STRUCT: return read_struct(r)
    if t in (T_LIST,T_SET):
        h=r.byte(); size=h>>4; et=h&15
        if size==15: size=r.varint()
        return [read_val(r,et) for _ in range(size)]
    if t==T_MAP:
        size=r.varint()
        if size==0: return {}
        h=r.byte(); kt=h>>4; vt=h&15
        return {read_val(r,kt):read_val(r,vt) for _ in range(size)}
    raise Exception('type '+str(t))

def read_struct(r):
    out={}; fid=0
    while True:
        h=r.byte(); t=h&15; delta=h>>4
        if t==0: break
        if delta: fid += delta
        else: fid = r.zig()
        out[fid]=read_val(r,t)
    return out

