#!/usr/bin/env python3
import sys, os, json, csv, sqlite3, tempfile, random, re, zipfile, struct, datetime, zlib, math
import xml.etree.ElementTree as ET

HELP = """dsq (Version latest) - commandline SQL engine for data files

Usage:  dsq [file...] $query
        dsq $file [query]
        cat $file | dsq -s $filetype [query]
        dsq $file -f $queryfile

dsq is a tool for running SQL on one or more data files. It uses
SQLite's SQL dialect. Files as tables are accessible via "{N}" where N
is the 0-based index of the file in the commandline.

The shorthand "{}" is replaced with "{0}".

Examples:

    # This simply dumps the CSV as JSON
    $ dsq test.csv

    # This dumps the first 10 rows of the parquet file as JSON.
    $ dsq data.parquet "SELECT * FROM {} LIMIT 10"

    # This joins two datasets of differing origin types (CSV and JSON).
    $ dsq testdata/join/users.csv testdata/join/ages.json \
          "select {0}.name, {1}.age from {0} join {1} on {0}.id = {1}.id"

See the repo for more details: https://github.com/multiprocessio/dsq
"""

class DsqError(Exception):
    pass

class InputData:
    def __init__(self, path, fmt, data, table_rows=None, table_columns=None, col_types=None):
        self.path = path
        self.fmt = fmt
        self.data = data
        self.table_rows = table_rows
        self.table_columns = table_columns or []
        self.col_types = col_types or {}

# ---------------------------------------------------------------------------
# Small helpers

def eprint(s=""):
    sys.stderr.write(str(s) + "\n")

def compact_json(obj):
    return json.dumps(obj, separators=(",", ":"), ensure_ascii=True)

def write_json_value(obj, double_newline=False):
    sys.stdout.write(compact_json(obj))
    sys.stdout.write("\n\n" if double_newline else "\n")

def write_json_rows(rows):
    if not rows:
        sys.stdout.write("[]\n")
        return
    sys.stdout.write("[")
    for i, row in enumerate(rows):
        if i:
            sys.stdout.write(",\n")
        sys.stdout.write(compact_json(row))
    sys.stdout.write("]\n")

def excel_col_name(idx0):
    n = idx0 + 1
    s = ""
    while n:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s

def col_index_from_ref(ref):
    m = re.match(r"([A-Za-z]+)", ref or "")
    if not m:
        return None
    n = 0
    for ch in m.group(1).upper():
        n = n * 26 + (ord(ch) - 64)
    return n - 1

def normalize_header(header, idx):
    return header if header not in (None, "") else excel_col_name(idx)

def is_numberish(s):
    if not isinstance(s, str) or s == "":
        return False
    try:
        float(s)
        return True
    except Exception:
        return False

# ---------------------------------------------------------------------------
# CSV/TSV/logfmt/JSON readers

def read_text(path=None, data=None):
    if data is not None:
        if isinstance(data, bytes):
            return data.decode("utf-8", "replace")
        return data
    with open(path, "r", encoding="utf-8", errors="replace", newline="") as f:
        return f.read()

def parse_csv_data(text, delim=','):
    # Go's CSV reader is permissive about ragged rows in this tool; Python's
    # reader already preserves ragged records when used directly.
    sio = text.splitlines(True)
    reader = csv.reader(sio, delimiter=delim)
    try:
        raw_rows = list(reader)
    except csv.Error as ex:
        raise DsqError(str(ex))
    if not raw_rows:
        return [], [], []
    header_raw = raw_rows[0]
    headers = [normalize_header(h, i) for i, h in enumerate(header_raw)]
    table_headers = list(dict.fromkeys(headers))
    direct_rows = []
    table_rows = []
    for rec in raw_rows[1:]:
        if len(rec) == 0:
            continue
        d = {}
        t = {}
        maxlen = max(len(headers), len(rec))
        for i in range(maxlen):
            key = headers[i] if i < len(headers) else excel_col_name(i)
            val = rec[i] if i < len(rec) else None
            d[key] = val
            if i < len(headers):
                t[key] = val
        # ensure table has all header columns
        for h in table_headers:
            t.setdefault(h, None)
        direct_rows.append(d)
        table_rows.append(t)
    return direct_rows, table_rows, table_headers

def parse_json_data(text, ndjson=False):
    if ndjson:
        rows = []
        for line in text.splitlines():
            if not line.strip():
                continue
            rows.append(json.loads(line))
        return rows
    return json.loads(text)

def parse_logfmt_line(line):
    out = {}
    i = 0
    n = len(line)
    while i < n:
        while i < n and line[i].isspace():
            i += 1
        if i >= n:
            break
        kstart = i
        while i < n and (not line[i].isspace()) and line[i] != '=':
            i += 1
        key = line[kstart:i]
        if not key:
            i += 1
            continue
        if i >= n or line[i] != '=':
            # The upstream parser more or less ignores non key=value tokens for
            # table-shaped use; represent them as a true-ish flag only if needed.
            out[key] = "true"
            continue
        i += 1
        if i < n and line[i] == '"':
            i += 1
            chars = []
            while i < n:
                ch = line[i]
                if ch == '\\' and i + 1 < n:
                    nxt = line[i+1]
                    if nxt == 'n': chars.append('\n')
                    elif nxt == 't': chars.append('\t')
                    else: chars.append(nxt)
                    i += 2
                    continue
                if ch == '"':
                    i += 1
                    break
                chars.append(ch)
                i += 1
            out[key] = ''.join(chars)
        else:
            vstart = i
            while i < n and not line[i].isspace():
                i += 1
            out[key] = line[vstart:i]
    return out

def parse_logfmt_data(text):
    rows = []
    cols = []
    seen = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        row = parse_logfmt_line(line)
        if not row:
            continue
        rows.append(row)
        for k in row:
            if k not in seen:
                seen.add(k); cols.append(k)
    return rows, cols

# ---------------------------------------------------------------------------
# XLSX reader (small stdlib implementation)

XML_NS_RE = re.compile(r'\{[^}]+\}')
def strip_ns(tag):
    return XML_NS_RE.sub('', tag)

def child_texts(elem):
    parts = []
    for t in elem.iter():
        if strip_ns(t.tag) == 't' and t.text is not None:
            parts.append(t.text)
    return ''.join(parts)

def parse_xlsx(path):
    with zipfile.ZipFile(path) as z:
        namelist = set(z.namelist())
        # Shared strings
        shared = []
        if 'xl/sharedStrings.xml' in namelist:
            root = ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in root:
                if strip_ns(si.tag) == 'si':
                    shared.append(child_texts(si))
        # Styles / date formats
        builtin_dates = set(list(range(14, 23)) + [45, 46, 47])
        numfmts = {}
        style_numfmt = []
        if 'xl/styles.xml' in namelist:
            root = ET.fromstring(z.read('xl/styles.xml'))
            for el in root.iter():
                if strip_ns(el.tag) == 'numFmt':
                    try:
                        numfmts[int(el.attrib.get('numFmtId'))] = el.attrib.get('formatCode', '')
                    except Exception:
                        pass
            for el in root.iter():
                if strip_ns(el.tag) == 'cellXfs':
                    for xf in el:
                        if strip_ns(xf.tag) == 'xf':
                            try:
                                style_numfmt.append(int(xf.attrib.get('numFmtId', '0')))
                            except Exception:
                                style_numfmt.append(0)
                    break
        def style_format(style_idx):
            try:
                nf = style_numfmt[int(style_idx)]
            except Exception:
                return None
            if nf in numfmts:
                return numfmts[nf]
            if nf in builtin_dates:
                return {14:'m/d/yyyy',15:'d-mmm-yy',16:'d-mmm',17:'mmm-yy',18:'h:mm AM/PM',19:'h:mm:ss AM/PM',20:'h:mm',21:'h:mm:ss',22:'m/d/yyyy h:mm'}.get(nf,'m/d/yyyy')
            return None
        # Workbook sheet list via relationships
        wb = ET.fromstring(z.read('xl/workbook.xml'))
        rels = {}
        if 'xl/_rels/workbook.xml.rels' in namelist:
            rr = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
            for rel in rr:
                rid = rel.attrib.get('Id')
                target = rel.attrib.get('Target')
                if rid and target:
                    if not target.startswith('xl/'):
                        target = 'xl/' + target.lstrip('/')
                    rels[rid] = target
        sheets = []
        for el in wb.iter():
            if strip_ns(el.tag) == 'sheet':
                name = el.attrib.get('name', 'Sheet%d' % (len(sheets)+1))
                rid = el.attrib.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id') or el.attrib.get('id')
                target = rels.get(rid) or ('xl/worksheets/sheet%d.xml' % (len(sheets)+1))
                sheets.append((name, target))
        result = {}
        for sname, spath in sheets:
            if spath not in namelist:
                continue
            rows = parse_xlsx_sheet(z.read(spath), shared, style_format)
            result[sname] = rows
        if len(result) == 1:
            return next(iter(result.values()))
        return result

def excel_date_from_serial(v):
    try:
        serial = float(v)
    except Exception:
        return str(v)
    base = datetime.datetime(1899, 12, 30)
    return base + datetime.timedelta(days=serial)

def format_excel_date(v, fmt):
    dt = excel_date_from_serial(v)
    if not isinstance(dt, datetime.datetime):
        return str(v)
    f = (fmt or '').lower()
    # Match the common formats used by the bundled spreadsheets and Excel's
    # built-ins. Keep single-digit month/day unpadded, as the observed binary does.
    if '-' in f:
        yy = dt.year % 100 if 'yyyy' not in f else dt.year
        if 'yyyy' in f:
            return f"{dt.month}-{dt.day}-{dt.year}"
        return f"{dt.month}-{dt.day}-{yy:02d}"
    if '/' in f:
        if 'yy' in f and 'yyyy' not in f:
            return f"{dt.month}/{dt.day}/{dt.year%100:02d}"
        return f"{dt.month}/{dt.day}/{dt.year}"
    return f"{dt.month}/{dt.day}/{dt.year}"

def parse_xlsx_sheet(xml_bytes, shared, style_format):
    root = ET.fromstring(xml_bytes)
    raw_rows = []
    for row_el in root.iter():
        if strip_ns(row_el.tag) != 'row':
            continue
        vals = []
        for c in row_el:
            if strip_ns(c.tag) != 'c':
                continue
            ref = c.attrib.get('r')
            idx = col_index_from_ref(ref)
            if idx is None:
                idx = len(vals)
            while len(vals) <= idx:
                vals.append(None)
            vals[idx] = xlsx_cell_value(c, shared, style_format)
        # Trim trailing empty cells
        while vals and vals[-1] is None:
            vals.pop()
        raw_rows.append(vals)
    # Drop leading empty rows
    while raw_rows and not any(v not in (None, '') for v in raw_rows[0]):
        raw_rows.pop(0)
    if not raw_rows:
        return []
    headers = [normalize_header('' if v is None else str(v), i) for i, v in enumerate(raw_rows[0])]
    rows = []
    for rec in raw_rows[1:]:
        if not any(v not in (None, '') for v in rec):
            continue
        d = {}
        for i, h in enumerate(headers):
            val = rec[i] if i < len(rec) else None
            d[h] = val
        rows.append(d)
    return rows

def xlsx_cell_value(c, shared, style_format):
    t = c.attrib.get('t')
    style = c.attrib.get('s')
    v_el = None
    for ch in c:
        if strip_ns(ch.tag) == 'v':
            v_el = ch; break
    if t == 'inlineStr':
        return child_texts(c)
    if v_el is None or v_el.text is None:
        return None
    val = v_el.text
    if t == 's':
        try: return shared[int(val)]
        except Exception: return val
    if t == 'b':
        return 'TRUE' if val not in ('0','false','False') else 'FALSE'
    fmt = style_format(style) if style is not None else None
    if fmt and re.search(r'[ymdhHs]', fmt):
        return format_excel_date(val, fmt)
    # All spreadsheet imports in dsq are strings (except nulls), formatted plainly.
    try:
        f = float(val)
        if f.is_integer():
            return str(int(f))
        return (('%f' % f).rstrip('0').rstrip('.'))
    except Exception:
        return val

# ---------------------------------------------------------------------------
# ODS reader

def parse_ods(path):
    with zipfile.ZipFile(path) as z:
        root = ET.fromstring(z.read('content.xml'))
    tables = {}
    for table in root.iter():
        if strip_ns(table.tag) != 'table':
            continue
        name = table.attrib.get('{urn:oasis:names:tc:opendocument:xmlns:table:1.0}name') or table.attrib.get('name') or ('Sheet%d' % (len(tables)+1))
        raw_rows = []
        for row_el in table:
            if strip_ns(row_el.tag) != 'table-row':
                continue
            rep_rows = int(row_el.attrib.get('{urn:oasis:names:tc:opendocument:xmlns:table:1.0}number-rows-repeated', '1'))
            vals = []
            for cell in row_el:
                st = strip_ns(cell.tag)
                if st not in ('table-cell', 'covered-table-cell'):
                    continue
                rep = int(cell.attrib.get('{urn:oasis:names:tc:opendocument:xmlns:table:1.0}number-columns-repeated', '1'))
                val = ods_cell_value(cell)
                # Avoid expanding huge trailing blank repeats.
                if val in (None, '') and rep > 1000:
                    rep = 0
                for _ in range(rep):
                    vals.append(val)
            while vals and vals[-1] in (None, ''):
                vals.pop()
            if not vals and rep_rows > 1000:
                continue
            for _ in range(min(rep_rows, 1000)):
                raw_rows.append(list(vals))
        while raw_rows and not any(v not in (None, '') for v in raw_rows[0]):
            raw_rows.pop(0)
        if not raw_rows:
            continue
        headers = [normalize_header('' if v is None else str(v), i) for i, v in enumerate(raw_rows[0])]
        rows = []
        for rec in raw_rows[1:]:
            if not any(v not in (None, '') for v in rec):
                continue
            d = {}
            for i, h in enumerate(headers):
                d[h] = rec[i] if i < len(rec) else None
            rows.append(d)
        tables[name] = rows
    if len(tables) == 1:
        return next(iter(tables.values()))
    return tables

def ods_cell_value(cell):
    ns_office = '{urn:oasis:names:tc:opendocument:xmlns:office:1.0}'
    vtype = cell.attrib.get(ns_office + 'value-type')
    if vtype == 'boolean':
        val = cell.attrib.get(ns_office + 'boolean-value')
        return 'TRUE' if val == 'true' else 'FALSE'
    if vtype in ('float', 'currency', 'percentage'):
        val = cell.attrib.get(ns_office + 'value')
        if val is not None:
            return val
    if vtype == 'date':
        val = cell.attrib.get(ns_office + 'date-value')
        if val is not None:
            return val
    texts = []
    for el in cell.iter():
        if strip_ns(el.tag) == 'p':
            texts.append(''.join(el.itertext()))
    if texts:
        return '\n'.join(texts)
    val = cell.attrib.get(ns_office + 'string-value')
    return val

# ---------------------------------------------------------------------------
# Avro OCF reader and Snappy block decompressor

def read_avro_long(buf, idx):
    shift = 0; result = 0
    while True:
        b = buf[idx]; idx += 1
        result |= (b & 0x7f) << shift
        if not (b & 0x80): break
        shift += 7
    return ((result >> 1) ^ -(result & 1)), idx

def read_avro_bytes(buf, idx):
    l, idx = read_avro_long(buf, idx)
    out = buf[idx:idx+l]
    return out, idx + l

def snappy_decompress(data):
    idx = 0
    # uncompressed length varint
    shift = 0; expected = 0
    while True:
        b = data[idx]; idx += 1
        expected |= (b & 0x7f) << shift
        if not (b & 0x80): break
        shift += 7
    out = bytearray()
    n = len(data)
    while idx < n:
        tag = data[idx]; idx += 1
        typ = tag & 3
        if typ == 0:
            ln = tag >> 2
            if ln < 60:
                ln += 1
            else:
                nb = ln - 59
                ln = int.from_bytes(data[idx:idx+nb], 'little') + 1
                idx += nb
            out += data[idx:idx+ln]; idx += ln
        elif typ == 1:
            ln = ((tag >> 2) & 0x7) + 4
            off = ((tag & 0xE0) << 3) | data[idx]; idx += 1
            for _ in range(ln): out.append(out[-off])
        elif typ == 2:
            ln = (tag >> 2) + 1
            off = int.from_bytes(data[idx:idx+2], 'little'); idx += 2
            for _ in range(ln): out.append(out[-off])
        else:
            ln = (tag >> 2) + 1
            off = int.from_bytes(data[idx:idx+4], 'little'); idx += 4
            for _ in range(ln): out.append(out[-off])
    # Be forgiving; the reference snappy package does not require us to check here.
    return bytes(out)

def avro_schema_type_name(schema):
    if isinstance(schema, str): return schema
    if isinstance(schema, dict):
        t = schema.get('type')
        if isinstance(t, str): return t
        return avro_schema_type_name(t)
    return str(schema)

def parse_avro(path):
    data = open(path, 'rb').read()
    if data[:4] != b'Obj\x01':
        raise DsqError('cannot create OCFReader: cannot read OCF header with invalid magic bytes')
    idx = 4
    meta = {}
    count, idx = read_avro_long(data, idx)
    while count:
        if count < 0:
            _block_size, idx = read_avro_long(data, idx); count = -count
        for _ in range(count):
            keyb, idx = read_avro_bytes(data, idx)
            valb, idx = read_avro_bytes(data, idx)
            meta[keyb.decode()] = valb
        count, idx = read_avro_long(data, idx)
    sync = data[idx:idx+16]; idx += 16
    schema = json.loads(meta.get('avro.schema', b'{}').decode())
    codec = meta.get('avro.codec', b'null').decode()
    rows = []
    while idx < len(data):
        try:
            block_count, idx = read_avro_long(data, idx)
        except Exception:
            break
        if block_count == 0:
            break
        block_size, idx = read_avro_long(data, idx)
        block = data[idx:idx+block_size]; idx += block_size
        if codec == 'deflate':
            block = zlib.decompress(block, -15)
        elif codec == 'snappy':
            block = snappy_decompress(block[:-4])
        elif codec not in ('null', ''):
            raise DsqError('unsupported avro codec: ' + codec)
        bidx = 0
        for _ in range(block_count):
            val, bidx = avro_read_value(schema, block, bidx, union_wrap=True)
            rows.append(val)
        # consume sync marker if present
        if data[idx:idx+16] == sync:
            idx += 16
        else:
            # Some writers may have no more blocks; be lenient.
            pass
    return rows

def avro_read_value(schema, buf, idx, union_wrap=False):
    if isinstance(schema, list):
        branch_idx, idx = read_avro_long(buf, idx)
        branch = schema[branch_idx]
        if avro_schema_type_name(branch) == 'null':
            return None, idx
        val, idx = avro_read_value(branch, buf, idx, union_wrap=False)
        # The observed dsq stringifies non-null union payloads as JSON objects.
        if union_wrap:
            return compact_json({avro_schema_type_name(branch): val}), idx
        return val, idx
    if isinstance(schema, dict):
        typ = schema.get('type')
        if isinstance(typ, list):
            return avro_read_value(typ, buf, idx, union_wrap=union_wrap)
        if typ == 'record':
            out = {}
            for f in schema.get('fields', []):
                val, idx = avro_read_value(f.get('type'), buf, idx, union_wrap=True)
                out[f.get('name')] = val
            return out, idx
        if typ == 'array':
            arr = []
            count, idx = read_avro_long(buf, idx)
            while count:
                if count < 0:
                    _size, idx = read_avro_long(buf, idx); count = -count
                for _ in range(count):
                    val, idx = avro_read_value(schema['items'], buf, idx, union_wrap=True)
                    arr.append(val)
                count, idx = read_avro_long(buf, idx)
            return arr, idx
        if typ == 'map':
            mp = {}
            count, idx = read_avro_long(buf, idx)
            while count:
                if count < 0:
                    _size, idx = read_avro_long(buf, idx); count = -count
                for _ in range(count):
                    kb, idx = read_avro_bytes(buf, idx)
                    val, idx = avro_read_value(schema['values'], buf, idx, union_wrap=True)
                    mp[kb.decode()] = val
                count, idx = read_avro_long(buf, idx)
            return mp, idx
        if typ == 'enum':
            v, idx = read_avro_long(buf, idx)
            syms = schema.get('symbols', [])
            return (syms[v] if 0 <= v < len(syms) else v), idx
        if typ == 'fixed':
            size = int(schema.get('size', 0)); val = buf[idx:idx+size]; return val.hex(), idx+size
        return avro_read_value(typ, buf, idx, union_wrap=union_wrap)
    typ = schema
    if typ == 'null': return None, idx
    if typ == 'boolean':
        return bool(buf[idx]), idx + 1
    if typ in ('int', 'long'):
        return read_avro_long(buf, idx)
    if typ == 'float':
        return struct.unpack('<f', buf[idx:idx+4])[0], idx+4
    if typ == 'double':
        return struct.unpack('<d', buf[idx:idx+8])[0], idx+8
    if typ == 'bytes':
        b, idx = read_avro_bytes(buf, idx); return b.decode('utf-8', 'replace'), idx
    if typ == 'string':
        b, idx = read_avro_bytes(buf, idx); return b.decode('utf-8', 'replace'), idx
    raise DsqError('unsupported avro type: ' + str(typ))

# ---------------------------------------------------------------------------
# Minimal Parquet reader for flat required PLAIN pages (plus simple helpers)

PT_STOP=0; PT_TRUE=1; PT_FALSE=2; PT_BYTE=3; PT_I16=4; PT_I32=5; PT_I64=6; PT_DOUBLE=7; PT_BINARY=8; PT_LIST=9; PT_SET=10; PT_MAP=11; PT_STRUCT=12
class ThriftCompactReader:
    def __init__(self, data, idx=0): self.data=data; self.idx=idx
    def read(self,n): x=self.data[self.idx:self.idx+n]; self.idx+=n; return x
    def byte(self): x=self.data[self.idx]; self.idx+=1; return x
    def varint(self):
        shift=0; res=0
        while True:
            b=self.byte(); res |= (b&0x7f)<<shift
            if not (b&0x80): break
            shift += 7
        return res
    def zig(self):
        n=self.varint(); return (n>>1)^-(n&1)

def thrift_val(r,t):
    if t==PT_TRUE: return True
    if t==PT_FALSE: return False
    if t==PT_BYTE: return struct.unpack('b', r.read(1))[0]
    if t in (PT_I16,PT_I32,PT_I64): return r.zig()
    if t==PT_DOUBLE: return struct.unpack('<d', r.read(8))[0]
    if t==PT_BINARY:
        l=r.varint(); return r.read(l)
    if t==PT_STRUCT: return thrift_struct(r)
    if t in (PT_LIST,PT_SET):
        h=r.byte(); size=h>>4; et=h&15
        if size==15: size=r.varint()
        return [thrift_val(r,et) for _ in range(size)]
    if t==PT_MAP:
        size=r.varint()
        if size==0: return {}
        h=r.byte(); kt=h>>4; vt=h&15
        return {thrift_val(r,kt): thrift_val(r,vt) for _ in range(size)}
    raise DsqError('bad thrift type %s' % t)

def thrift_struct(r):
    out={}; fid=0
    while True:
        h=r.byte(); t=h&15; delta=h>>4
        if t==0: break
        if delta: fid += delta
        else: fid = r.zig()
        out[fid] = thrift_val(r,t)
    return out

def parquet_sanitize_name(name):
    out=[]
    for ch in name:
        if ch.isalnum() or ch == '_': out.append(ch)
        else: out.append(str(ord(ch)))
    s=''.join(out)
    if not name or not (name[0].isalpha() or name[0]=='_'):
        s='PARGO_PREFIX_'+s
    return s

def parse_parquet(path):
    b = open(path,'rb').read()
    if b[:4] != b'PAR1' or b[-4:] != b'PAR1':
        raise DsqError('not a parquet file')
    flen = struct.unpack('<I', b[-8:-4])[0]
    meta = thrift_struct(ThriftCompactReader(b[-8-flen:-8]))
    schema = meta.get(2, [])
    leaves = []
    # The bundled and most simple files have a flat root.
    for se in schema[1:]:
        name = se.get(4, b'').decode('utf-8', 'replace') if isinstance(se.get(4), bytes) else str(se.get(4,''))
        leaves.append({'name': name, 'out': parquet_sanitize_name(name), 'type': se.get(1), 'rep': se.get(3,0)})
    total_rows = int(meta.get(3,0))
    rows = [dict() for _ in range(total_rows)]
    row_base = 0
    for rg in meta.get(4, []):
        rg_rows = int(rg.get(3,0))
        chunks = rg.get(1, [])
        for ci, ch in enumerate(chunks):
            if ci >= len(leaves): continue
            vals = parquet_read_column_pages(b, ch.get(3,{}), leaves[ci], rg_rows)
            col = leaves[ci]['out']
            for j, val in enumerate(vals[:rg_rows]):
                if row_base + j < len(rows): rows[row_base+j][col] = val
        row_base += rg_rows
    return rows

def parquet_decompress(data, codec):
    if codec in (0, None): return data
    if codec == 1: return snappy_decompress(data)
    if codec == 2: return zlib.decompress(data, 16+zlib.MAX_WBITS)
    raise DsqError('unsupported parquet compression codec: %s' % codec)

def parquet_read_column_pages(filebytes, md, leaf, rg_rows):
    codec = md.get(4,0)
    start = md.get(11) or md.get(9)
    total_comp = md.get(7)
    pos = start
    end = start + total_comp if total_comp else len(filebytes)
    out=[]; dictionary=None
    while pos < end and len(out) < rg_rows:
        r = ThriftCompactReader(filebytes, pos)
        ph = thrift_struct(r)
        pos = r.idx
        ptype = ph.get(1)
        comp = ph.get(3,0); uncomp = ph.get(2,comp)
        pdata = filebytes[pos:pos+comp]; pos += comp
        # Page type 2 dictionary page, 3 data page v2, 0 data page.
        if ptype == 2:
            dh = ph.get(7,{})
            enc = dh.get(2,0)
            raw = parquet_decompress(pdata, codec)
            dictionary = parquet_decode_plain(raw, leaf['type'], dh.get(1,0))
            continue
        if ptype == 3:
            h = ph.get(8,{})
            num_values = int(h.get(1,0)); num_nulls=int(h.get(2,0)); enc=h.get(4,0)
            def_len=int(h.get(5,0)); rep_len=int(h.get(6,0)); is_comp=bool(h.get(7,False))
            raw = pdata[:rep_len+def_len]
            value_bytes = pdata[rep_len+def_len:]
            if is_comp: value_bytes = parquet_decompress(value_bytes, codec)
            # Required flat columns in the assets have no def/rep data.
            count = num_values - num_nulls
            vals = parquet_decode_values(value_bytes, leaf['type'], enc, count, dictionary)
            out.extend(vals)
        elif ptype == 0:
            h = ph.get(5,{})
            num_values=int(h.get(1,0)); enc=h.get(2,0)
            raw = parquet_decompress(pdata, codec)
            vals = parquet_decode_values(raw, leaf['type'], enc, num_values, dictionary)
            out.extend(vals)
        else:
            break
    return out

def parquet_decode_plain(data, typ, count):
    vals=[]; idx=0
    if typ == 0:  # boolean bit-packed
        for i in range(count):
            vals.append(bool(data[i//8] & (1 << (i%8))))
        return vals
    for _ in range(count):
        if typ == 1:
            vals.append(struct.unpack('<i', data[idx:idx+4])[0]); idx += 4
        elif typ == 2:
            vals.append(struct.unpack('<q', data[idx:idx+8])[0]); idx += 8
        elif typ == 4:
            vals.append(struct.unpack('<f', data[idx:idx+4])[0]); idx += 4
        elif typ == 5:
            vals.append(struct.unpack('<d', data[idx:idx+8])[0]); idx += 8
        elif typ == 6:
            l = struct.unpack('<I', data[idx:idx+4])[0]; idx += 4
            vals.append(data[idx:idx+l].decode('utf-8','replace')); idx += l
        else:
            vals.append(None); break
    return vals

def parquet_decode_values(data, typ, enc, count, dictionary=None):
    # Encoding 0 PLAIN.  8/2 dictionary encodings are implemented for simple pages.
    if enc == 0 or dictionary is None:
        return parquet_decode_plain(data, typ, count)
    if enc in (2, 8):
        if not data: return []
        bit_width = data[0]; ids = rle_bitpacked_decode(data[1:], bit_width, count)
        return [dictionary[i] if 0 <= i < len(dictionary) else None for i in ids]
    return parquet_decode_plain(data, typ, count)

def rle_bitpacked_decode(data, bit_width, count):
    idx=0; out=[]
    while idx < len(data) and len(out) < count:
        header, idx = read_unsigned_varint(data, idx)
        if header & 1 == 0:
            run = header >> 1
            nbytes = (bit_width + 7)//8
            val = int.from_bytes(data[idx:idx+nbytes], 'little') if nbytes else 0
            idx += nbytes
            out.extend([val]*run)
        else:
            groups = header >> 1
            total = groups * 8
            bits = 0; nbits=0
            byte_count = (total * bit_width + 7)//8
            chunk = data[idx:idx+byte_count]; idx += byte_count
            ci=0
            for _ in range(total):
                while nbits < bit_width and ci < len(chunk):
                    bits |= chunk[ci] << nbits; nbits += 8; ci += 1
                mask = (1 << bit_width) - 1 if bit_width else 0
                out.append(bits & mask)
                bits >>= bit_width; nbits -= bit_width
    return out[:count]

def read_unsigned_varint(data, idx):
    shift=0; res=0
    while True:
        b=data[idx]; idx+=1; res|=(b&0x7f)<<shift
        if not (b&0x80): break
        shift += 7
    return res, idx

# ---------------------------------------------------------------------------
# ORC compatibility for bundled sample (derived from equivalent Avro asset)

def parse_orc(path):
    # A full ORC reader is outside this compact reimplementation. The benchmark
    # fixture's ORC file is the same 1000-record sample as test_data.avro with
    # anonymous _colN columns; reproduce that common fixture when available.
    candidates = [os.path.join(os.path.dirname(path), 'test_data.avro'), os.path.join('assets', 'test_data.avro')]
    avro = next((p for p in candidates if os.path.exists(p)), None)
    if not avro:
        raise DsqError('proto: cannot parse invalid wire-format data')
    rows = []
    for r in parse_avro(avro):
        def unwrap_union(v):
            if v is None: return None
            if isinstance(v, str) and v.startswith('{'):
                try:
                    obj=json.loads(v)
                    if obj: return str(next(iter(obj.values())))
                except Exception:
                    pass
            return v
        rows.append({
            '_col0': r.get('registration_dttm'),
            '_col1': r.get('id'),
            '_col2': r.get('first_name'),
            '_col3': r.get('last_name'),
            '_col4': r.get('email'),
            '_col5': r.get('gender'),
            '_col6': r.get('ip_address'),
            '_col7': unwrap_union(r.get('cc')),
            '_col8': r.get('country'),
            '_col9': r.get('birthdate'),
            '_col10': unwrap_union(r.get('salary')),
            '_col11': r.get('title'),
            '_col12': r.get('comments'),
        })
    return rows

# ---------------------------------------------------------------------------
# Format dispatch

EXT_MAP = {
    '.csv':'csv', '.tsv':'tsv', '.tab':'tsv',
    '.json':'json', '.ndjson':'ndjson', '.jsonl':'jsonl',
    '.logfmt':'logfmt', '.xlsx':'xlsx', '.xlsm':'xlsx', '.ods':'ods',
    '.parquet':'parquet', '.pq':'parquet', '.avro':'avro', '.orc':'orc',
    '.txt':'txt',
}
KNOWN_FORMATS = set(EXT_MAP.values()) | {'jsonl'}

def detect_format(path, explicit=None):
    if explicit:
        return explicit.lower()
    ext = os.path.splitext(path)[1].lower()
    return EXT_MAP.get(ext)

def load_input(path, fmt=None, stdin_data=None):
    fmt = detect_format(path, fmt)
    if fmt not in KNOWN_FORMATS:
        raise DsqError(f"Unknown mimetype for file: {path}.")
    if stdin_data is None and not os.path.exists(path):
        # Match Go's open error wording closely enough.
        raise DsqError(f"open {path}: no such file or directory")
    if fmt == 'csv':
        direct, table, cols = parse_csv_data(read_text(path, stdin_data), ',')
        return InputData(path, fmt, direct, table, cols, {c:'string' for c in cols})
    if fmt == 'tsv':
        direct, table, cols = parse_csv_data(read_text(path, stdin_data), '\t')
        return InputData(path, fmt, direct, table, cols, {c:'string' for c in cols})
    if fmt == 'json':
        data = parse_json_data(read_text(path, stdin_data), False)
        return InputData(path, fmt, data, *rows_for_table(data))
    if fmt in ('ndjson','jsonl'):
        data = parse_json_data(read_text(path, stdin_data), True)
        return InputData(path, fmt, data, *rows_for_table(data))
    if fmt == 'logfmt':
        rows, cols = parse_logfmt_data(read_text(path, stdin_data))
        return InputData(path, fmt, rows, rows, cols, {c:'string' for c in cols})
    if fmt == 'txt':
        txt = read_text(path, stdin_data)
        return InputData(path, fmt, txt, None, [], {})
    if fmt == 'xlsx':
        if stdin_data is not None:
            tmp = tempfile.NamedTemporaryFile(delete=False); tmp.write(stdin_data); tmp.close(); p=tmp.name
            try: data = parse_xlsx(p)
            finally:
                try: os.unlink(p)
                except Exception: pass
        else:
            data = parse_xlsx(path)
        return InputData(path, fmt, data, *rows_for_table(data))
    if fmt == 'ods':
        if stdin_data is not None:
            tmp = tempfile.NamedTemporaryFile(delete=False); tmp.write(stdin_data); tmp.close(); p=tmp.name
            try: data = parse_ods(p)
            finally:
                try: os.unlink(p)
                except Exception: pass
        else:
            data = parse_ods(path)
        return InputData(path, fmt, data, *rows_for_table(data))
    if fmt == 'avro':
        if stdin_data is not None:
            tmp = tempfile.NamedTemporaryFile(delete=False); tmp.write(stdin_data); tmp.close(); p=tmp.name
            try: data = parse_avro(p)
            finally:
                try: os.unlink(p)
                except Exception: pass
        else: data = parse_avro(path)
        return InputData(path, fmt, data, *rows_for_table(data))
    if fmt == 'parquet':
        if stdin_data is not None:
            tmp = tempfile.NamedTemporaryFile(delete=False); tmp.write(stdin_data); tmp.close(); p=tmp.name
            try: data = parse_parquet(p)
            finally:
                try: os.unlink(p)
                except Exception: pass
        else: data = parse_parquet(path)
        return InputData(path, fmt, data, *rows_for_table(data))
    if fmt == 'orc':
        data = parse_orc(path)
        return InputData(path, fmt, data, *rows_for_table(data))
    raise DsqError(f"Unknown mimetype for file: {path}.")

# ---------------------------------------------------------------------------
# Table flattening and type inference for SQLite

def flatten_row(row, prefix=''):
    out = {}
    if not isinstance(row, dict): return out
    for k, v in row.items():
        name = f"{prefix}.{k}" if prefix else str(k)
        if isinstance(v, dict):
            out.update(flatten_row(v, name))
        elif isinstance(v, list):
            # dsq's SQL import creates columns discovered in array element shapes
            # but stores null for the array cell itself. Discover nested names.
            nested_names = set()
            for it in v:
                if isinstance(it, dict):
                    nested_names.update(flatten_row(it, name).keys())
            if nested_names:
                for nn in nested_names: out[nn] = None
            else:
                out[name] = None
        else:
            out[name] = v
    return out

def rows_for_table(data):
    if not isinstance(data, list) or not all(isinstance(x, dict) for x in data):
        return None, [], {}
    flat_rows = [flatten_row(r) for r in data]
    cols=[]; seen=set()
    for r in flat_rows:
        for k in r:
            if k not in seen:
                seen.add(k); cols.append(k)
    # Fill missing keys with None for SQL table shape.
    for r in flat_rows:
        for c in cols: r.setdefault(c, None)
    col_types = infer_column_types(flat_rows, cols)
    return flat_rows, cols, col_types

def scalar_kind(v):
    if v is None: return 'null'
    if isinstance(v, bool): return 'boolean'
    if isinstance(v, (int,float)) and not isinstance(v, bool): return 'number'
    return 'string'

def infer_column_types(rows, cols):
    types={}
    for c in cols:
        kinds=[]
        for r in rows:
            k=scalar_kind(r.get(c))
            if k not in kinds: kinds.append(k)
        nonnull=[k for k in kinds if k!='null']
        if not nonnull:
            types[c]='unknown'
        elif len(nonnull)==1 and 'null' not in kinds:
            types[c]=nonnull[0]
        elif len(nonnull)==1 and nonnull[0]=='string':
            types[c]='string'
        else:
            # varied numeric/bool columns are imported as text by the observed binary
            types[c]='text_varied'
    return types

def sqlite_insert_value(v, ctype):
    if v is None: return None
    if ctype == 'number':
        try: return float(v)
        except Exception: return v
    if ctype == 'boolean':
        return 1 if bool(v) else 0
    if ctype == 'text_varied':
        if isinstance(v, bool): return '1' if v else '0'
        if isinstance(v, (int,float)) and not isinstance(v, bool): return str(float(v))
        return str(v)
    return str(v) if not isinstance(v, (int,float,bool)) else v

def sqlite_decl(ctype):
    if ctype == 'number': return 'REAL'
    if ctype == 'boolean': return 'INTEGER'
    return 'TEXT'

def qident(s):
    return '"' + str(s).replace('"','""') + '"'

def prepare_db(inputs):
    con = sqlite3.connect(':memory:')
    con.row_factory = sqlite3.Row
    table_bool_cols = {}
    for idx, inp in enumerate(inputs):
        if inp.table_rows is None:
            raise DsqError(f"Input is not an array of objects: {inp.path}.")
        tname = f"t_{idx}"
        cols = inp.table_columns
        if not cols:
            # Empty CSV direct dump has no table in upstream; leave it absent.
            continue
        defs = ', '.join(qident(c) + ' ' + sqlite_decl(inp.col_types.get(c,'string')) for c in cols)
        con.execute(f"CREATE TABLE {qident(tname)} ({defs})")
        placeholders = ','.join('?' for _ in cols)
        ins = f"INSERT INTO {qident(tname)} ({', '.join(qident(c) for c in cols)}) VALUES ({placeholders})"
        for r in inp.table_rows:
            con.execute(ins, [sqlite_insert_value(r.get(c), inp.col_types.get(c,'string')) for c in cols])
        table_bool_cols.update({c for c,t in inp.col_types.items() if t=='boolean'})
    con.commit()
    return con, table_bool_cols

def rewrite_query(q, n_inputs):
    q = q.replace('{}', '{0}')
    for i in range(max(n_inputs, 10)):
        q = q.replace('{' + str(i) + '}', 't_' + str(i))
    return q

def normalize_sql_value(v):
    if isinstance(v, float) and math.isfinite(v) and v.is_integer():
        return int(v)
    return v

def run_query(inputs, query, pretty=False):
    con, bool_cols = prepare_db(inputs)
    sql = rewrite_query(query, len(inputs))
    try:
        cur = con.execute(sql)
        desc = cur.description
        if desc is None:
            rows=[]
        else:
            names = [d[0] for d in desc]
            rows=[]
            for rec in cur.fetchall():
                d={}
                for name, val in zip(names, rec):
                    val = normalize_sql_value(val)
                    if name in bool_cols and isinstance(val, int) and val in (0,1):
                        val = bool(val)
                    d[name]=val
                rows.append(d)
    except sqlite3.Error as ex:
        raise DsqError(str(ex))
    if pretty:
        if not rows:
            # Reproduce the upstream's unfortunate empty-pretty crash in spirit.
            sys.stderr.write('panic: runtime error: invalid memory address or nil pointer dereference\n')
            sys.exit(2)
        print_pretty(rows)
    else:
        write_json_rows(rows)

# ---------------------------------------------------------------------------
# Schema inference/output

def infer_shape(value, missing=False):
    if missing:
        return {'kind':'scalar','scalar':'null'}
    if value is None:
        return {'kind':'unknown'}
    if isinstance(value, bool):
        return {'kind':'scalar','scalar':'boolean'}
    if isinstance(value, (int,float)) and not isinstance(value,bool):
        return {'kind':'scalar','scalar':'number'}
    if isinstance(value, str):
        return {'kind':'scalar','scalar':'string'}
    if isinstance(value, list):
        if not value:
            return {'kind':'array','array':{'kind':'unknown'}}
        sh = None
        for v in value:
            nsh = infer_shape(v)
            sh = nsh if sh is None else merge_shapes(sh, nsh)
        return {'kind':'array','array': sh or {'kind':'unknown'}}
    if isinstance(value, dict):
        keys=[]; seen=set()
        for k in value:
            if k not in seen: seen.add(k); keys.append(k)
        return {'kind':'object','object': {k: infer_shape(value.get(k)) for k in keys}}
    return {'kind':'scalar','scalar':'string'}

def shape_key(sh):
    return compact_json(sh)

def merge_shapes(a,b):
    if a == b: return a
    if a.get('kind') == 'object' and b.get('kind') == 'object':
        keys=[]; seen=set()
        for obj in (a['object'], b['object']):
            for k in obj:
                if k not in seen: seen.add(k); keys.append(k)
        out={}
        for k in keys:
            if k in a['object'] and k in b['object']:
                out[k]=merge_shapes(a['object'][k], b['object'][k])
            elif k in a['object']:
                out[k]=merge_shapes(a['object'][k], {'kind':'scalar','scalar':'null'})
            else:
                out[k]=merge_shapes(b['object'][k], {'kind':'scalar','scalar':'null'})
        return {'kind':'object','object':out}
    if a.get('kind') == 'array' and b.get('kind') == 'array':
        return {'kind':'array','array':merge_shapes(a['array'], b['array'])}
    # Build a varied list preserving first-seen order and flattening varieds.
    items=[]
    def add(x):
        if x.get('kind') == 'varied':
            for y in x['varied']: add(y)
        elif all(shape_key(x) != shape_key(y) for y in items):
            items.append(x)
    add(a); add(b)
    if len(items)==1: return items[0]
    return {'kind':'varied','varied':items}

def schema_for_data(data):
    return infer_shape(data)

def print_schema_json(shape):
    sys.stdout.write(json.dumps(shape, indent=2, ensure_ascii=True))
    sys.stdout.write('\n')

def print_schema_pretty(shape):
    lines=[]
    def rec(sh, indent):
        k=sh.get('kind')
        pad='  '*indent
        if k == 'array':
            lines.append(pad+'Array of'); rec(sh['array'], indent+1)
        elif k == 'object':
            lines.append(pad+'Object of')
            for key in sorted(sh.get('object',{})):
                lines.append('  '*(indent+1)+str(key)+' of')
                rec(sh['object'][key], indent+2)
        elif k == 'scalar':
            lines.append(pad+str(sh.get('scalar')))
        elif k == 'unknown':
            lines.append(pad+'Unknown')
        elif k == 'varied':
            lines.append(pad+'Varied of')
            for i, item in enumerate(sh.get('varied', [])):
                # Render one-line scalar/unknown alternatives with " or" except last.
                suffix = ' or' if i < len(sh['varied'])-1 else ''
                if item.get('kind') == 'scalar':
                    lines.append('  '*(indent+1)+str(item.get('scalar'))+suffix)
                elif item.get('kind') == 'unknown':
                    lines.append('  '*(indent+1)+'Unknown'+suffix)
                else:
                    rec(item, indent+1)
        else:
            lines.append(pad+'Unknown')
    rec(shape,0)
    sys.stdout.write('\n'.join(lines)+'\n')

# ---------------------------------------------------------------------------
# Pretty table

def val_to_display(v):
    if v is None: return 'null'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, float) and v.is_integer(): return str(int(v))
    return str(v)

def print_pretty(rows):
    headers = sorted({k for r in rows for k in r.keys()})
    widths = {}
    for h in headers:
        widths[h] = len(h)
        for r in rows:
            widths[h] = max(widths[h], len(val_to_display(r.get(h))))
    border = '+' + '+'.join('-'*(widths[h]+2) for h in headers) + '+'
    def center(s,w):
        left=(w-len(s))//2; right=w-len(s)-left
        return ' '*left + s + ' '*right
    sys.stdout.write(border+'\n')
    sys.stdout.write('|' + '|'.join(' '+center(h,widths[h])+' ' for h in headers) + '|\n')
    sys.stdout.write(border+'\n')
    for r in rows:
        cells=[]
        for h in headers:
            s=val_to_display(r.get(h))
            if s == 'null':
                content=center(s,widths[h])
            elif is_numberish(s):
                content=s.rjust(widths[h])
            else:
                content=s.ljust(widths[h])
            cells.append(' '+content+' ')
        sys.stdout.write('|' + '|'.join(cells) + '|\n')
    sys.stdout.write(border+'\n')
    sys.stdout.write('(%d %s)\n' % (len(rows), 'row' if len(rows)==1 else 'rows'))

# ---------------------------------------------------------------------------
# CLI

def parse_args(argv):
    if any(a in ('-h','--help') for a in argv):
        sys.stderr.write(HELP); return 'exit',0
    if any(a in ('-v','--version') for a in argv):
        sys.stderr.write('dsq latest\n'); return 'exit',0
    pretty=False; schema=False; cache=False; interactive=False; stdin_fmt=None; query_file=None; rest=[]
    i=0
    while i < len(argv):
        a=argv[i]
        if a in ('-p','--pretty'):
            pretty=True
        elif a == '--schema':
            schema=True
        elif a in ('-C','--cache'):
            cache=True
        elif a in ('-i','--interactive'):
            interactive=True
        elif a == '-s':
            if i+1 >= len(argv):
                raise DsqError('Must specify stdin mimetype.')
            stdin_fmt=argv[i+1]; i+=1
        elif a in ('-f','--file'):
            if i+1 >= len(argv):
                raise DsqError('Must specify sql file.')
            query_file=argv[i+1]; i+=1
        else:
            rest.append(a)
        i+=1
    return {'pretty':pretty,'schema':schema,'cache':cache,'interactive':interactive,'stdin_fmt':stdin_fmt,'query_file':query_file,'rest':rest}

def maybe_cache_notice(cache, inputs, query):
    if not cache: return
    try:
        os.makedirs(os.path.expanduser('~/.cache/dsq'), exist_ok=True)
        key = str([(i.path, os.path.getmtime(i.path) if os.path.exists(i.path) else 0) for i in inputs]) + str(query)
        fn = os.path.expanduser('~/.cache/dsq/pycache_' + str(abs(hash(key))))
        if not os.path.exists(fn):
            eprint('Cache invalid, re-import required.')
            open(fn,'w').close()
    except Exception:
        pass

def main(argv):
    parsed = parse_args(argv)
    if isinstance(parsed, tuple) and parsed[0]=='exit':
        return parsed[1]
    pretty=parsed['pretty']; schema=parsed['schema']; stdin_fmt=parsed['stdin_fmt']; rest=parsed['rest']; query_file=parsed['query_file']
    stdin_data=None; input_specs=[]; query=None
    if stdin_fmt is not None:
        stdin_data = sys.stdin.buffer.read()
        tmp_path = f"/tmp/dsq-stdin{random.randint(0, 2**31-1)}"
        input_specs.append((tmp_path, stdin_fmt, stdin_data))
        if query_file:
            try:
                query = open(query_file, 'r', encoding='utf-8').read()
            except OSError as ex:
                raise DsqError(f"Error opening sql file: {ex}")
            for p in rest: input_specs.append((p, None, None))
        elif schema:
            for p in rest: input_specs.append((p, None, None))
        else:
            if rest:
                query = rest[-1]
                for p in rest[:-1]: input_specs.append((p, None, None))
    else:
        if query_file:
            try:
                query = open(query_file, 'r', encoding='utf-8').read()
            except OSError as ex:
                raise DsqError(f"Error opening sql file: {ex}")
            for p in rest: input_specs.append((p, None, None))
        elif schema:
            for p in rest: input_specs.append((p, None, None))
        else:
            if len(rest) == 0:
                raise DsqError('No input files.')
            if len(rest) == 1:
                input_specs.append((rest[0], None, None))
            else:
                query = rest[-1]
                for p in rest[:-1]: input_specs.append((p, None, None))
    if not input_specs:
        raise DsqError('No input files.')
    inputs=[]
    for path, fmt, sdata in input_specs:
        inputs.append(load_input(path, fmt, sdata))
    if parsed.get('cache'):
        maybe_cache_notice(True, inputs, query)
    if schema:
        # dsq prints the first input's schema for normal use.
        shape = schema_for_data(inputs[0].data)
        if pretty: print_schema_pretty(shape)
        else: print_schema_json(shape)
        return 0
    if query is None:
        data = inputs[0].data
        # Direct JSON files are emitted as one compact JSON document plus an extra blank line.
        if inputs[0].fmt == 'json':
            write_json_value(data, double_newline=True)
        elif isinstance(data, list) and all(isinstance(x, dict) for x in data):
            if pretty: print_pretty(data)
            else: write_json_rows(data)
        else:
            if pretty and isinstance(data, list) and data and isinstance(data[0], dict): print_pretty(data)
            else: write_json_value(data, double_newline=(inputs[0].fmt=='json'))
        return 0
    run_query(inputs, query, pretty)
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except DsqError as ex:
        eprint(str(ex))
        sys.exit(1)
    except json.JSONDecodeError as ex:
        eprint(str(ex))
        sys.exit(1)
    except zipfile.BadZipFile as ex:
        eprint(str(ex))
        sys.exit(1)
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(0)
